SourceCode.Declaration:
[DataContract]
public class MXGSResponse
{
    boolean success;
    str     error;
    List    messages;
    str     result;
}

Method.Source:
public void new()
{
    messages = new List(Types::Class);
}

[DataMember("Success")]
public boolean parmSuccess(boolean _success = success)
{
    success = _success;
    return success;
}

[DataMember("Error")]
public str parmError(str _error = error)
{
    error = _error;
    return error;
}

[DataMember("Messages"), DataCollection(Types::Class, classStr(MXGSMessage))]
public List parmMessages(List _messages = messages)
{
    messages = _messages;
    return messages;
}

public void addMessage(str _type, str _text)
{
    MXGSMessage message = new MXGSMessage();

    message.parmType(_type);
    message.parmText(_text);
    messages.addEnd(message);
}

[DataMember("Result")]
public str parmResult(str _result = result)
{
    result = _result;
    return result;
}
